type Page = 'home'|'stock'|'notes'|'settings'
type DetailTab = 'overview'|'trend'|'fundamentals'|'issues'|'ai'
type Period = '1M'|'3M'|'6M'|'1Y'|'3Y'|'5Y'
type QuickPeriod = '3M'|'1Y'|'3Y'
type SortKey = keyof StockSnapshot | `mdd${number}`
type Column = {key:SortKey;label:string;kind:'text'|'money'|'percent'|'cap'|'number';sticky?:'ticker'|'company'}
type ApiConfig = {sheetsKey:string;sheetId:string;supabaseUrl:string;supabaseAnonKey:string;openAiKey:string}
type ApiTextKey = keyof ApiConfig
type Connection = 'idle'|'testing'|'ok'|'error'

const emptyConfig:ApiConfig={sheetsKey:'',sheetId:'',supabaseUrl:'',supabaseAnonKey:'',openAiKey:''}
const APP_VERSION='v2.4.3'
const tags=['가격','실적','이슈','리스크','전략']
const periods:Period[]=['1M','3M','6M','1Y','3Y','5Y']
const currentYear=new Date().getUTCFullYear()
const mddYears=[currentYear-4,currentYear-3,currentYear-2,currentYear-1,currentYear]
const columns:Column[]=[
  {key:'ticker',label:'티커',kind:'text',sticky:'ticker'},{key:'company',label:'종목명',kind:'text',sticky:'company'},{key:'sector',label:'업종',kind:'text'},
  {key:'marketCap',label:'시가총액',kind:'cap'},{key:'pe',label:'PER',kind:'number'},{key:'eps',label:'EPS',kind:'money'},{key:'price',label:'현재가',kind:'money'},
  {key:'changePercent',label:'전일대비',kind:'percent'},{key:'ath',label:'ATH',kind:'money'},{key:'high52',label:'52주 고점',kind:'money'},{key:'drawdown52',label:'52주 고점 대비',kind:'percent'},
  {key:'low52',label:'52주 저점',kind:'money'},{key:'atl',label:'ATL',kind:'money'},...mddYears.map(year=>({key:`mdd${year}` as SortKey,label:`MDD ${year}`,kind:'percent' as const})),
  {key:'yearOpen',label:'연초가',kind:'money'},{key:'ytdReturn',label:'YTD',kind:'percent'},
]
const detailTabs:{key:DetailTab;label:string}[]=[{key:'overview',label:'개요'},{key:'trend',label:'가격·추세'},{key:'fundamentals',label:'기업·실적'},{key:'issues',label:'뉴스·이슈'},{key:'ai',label:'AI 분석'}]
const getValue=(stock:StockSnapshot,key:SortKey):MetricValue|string|null=>key.startsWith('mdd')?stock.mdd[Number(key.slice(3))]:stock[key as keyof StockSnapshot] as MetricValue|string|null
const fmt=(value:MetricValue|string|null,kind:Column['kind'])=>{if(value===null||value===undefined||value==='')return '—';if(typeof value==='string')return value;if(kind==='percent')return `${value>0?'+':''}${(value*100).toFixed(2)}%`;if(kind==='cap')return value>=1e12?`$${(value/1e12).toFixed(2)}T`:value>=1e9?`$${(value/1e9).toFixed(1)}B`:`$${(value/1e6).toFixed(0)}M`;if(kind==='money')return `$${value.toLocaleString('en-US',{maximumFractionDigits:2})}`;return value.toLocaleString('en-US',{maximumFractionDigits:2})}
const tone=(value:MetricValue)=>(value??0)>0?'positive':(value??0)<0?'negative':''
const loadJson=<T,>(key:string,fallback:T):T=>{try{return JSON.parse(localStorage.getItem(key)??'') as T}catch{return fallback}}
const subscribeHydration=()=>()=>{}
const formatUpdatedAt=(value:string|null)=>value?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)):'—'
const quickChartData=(history:StockSnapshot['priceHistory'],period:QuickPeriod,periodReturn:MetricValue)=>{const latest=history.at(-1)?.date;if(!latest)return{data:[],sufficient:false};const start=new Date(`${latest}T00:00:00Z`);if(period==='3M')start.setUTCMonth(start.getUTCMonth()-3);else start.setUTCFullYear(start.getUTCFullYear()-(period==='1Y'?1:3));const earliest=history[0]?.date;const tolerance=new Date(start);tolerance.setUTCDate(tolerance.getUTCDate()+10);if(!earliest||earliest>tolerance.toISOString().slice(0,10)||periodReturn===null)return{data:[],sufficient:false};const filtered=history.filter(point=>point.date>=start.toISOString().slice(0,10)).map(point=>({date:point.date,price:point.adjustedClose??point.close}));if(filtered.length<=180)return{data:filtered,sufficient:true};const sampled=Array.from({length:180},(_,index)=>filtered[Math.round(index*(filtered.length-1)/179)]);return{data:Array.from(new Map(sampled.map(point=>[point.date,point])).values()),sufficient:true}}

function App(){
  const hydrated=useSyncExternalStore(subscribeHydration,()=>true,()=>false)
  const [page,setPage]=useState<Page>('home'),[detailTab,setDetailTab]=useState<DetailTab>('overview')
  const [query,setQuery]=useState(''),[selectedTicker,setSelectedTicker]=useState(defaultCatalog.stocks[0].ticker),[quickTicker,setQuickTicker]=useState<string|null>(null)
  const [sort,setSort]=useState<{key:SortKey;dir:1|-1}>({key:'marketCap',dir:-1}),[mobileNav,setMobileNav]=useState(false)
  const [allStocks,setAllStocks]=useState(defaultStockSnapshots),[dataMode,setDataMode]=useState<DataMode>('fallback'),[marketDate,setMarketDate]=useState<string|null>(null),[updatedAt,setUpdatedAt]=useState<string|null>(null),[loading,setLoading]=useState(true)
  const [catalog,setCatalog]=useState<MarketCatalog>(defaultCatalog),[selectedGroup,setSelectedGroup]=useState(defaultCatalog.groups[0].id),[marketOverview,setMarketOverview]=useState<MarketOverviewItem[]>(emptyMarketOverview)
  const [validation,setValidation]=useState<ValidationRow[]>([])
  const [refreshState,setRefreshState]=useState<RefreshState>(null),[refreshing,setRefreshing]=useState(false),[refreshMessage,setRefreshMessage]=useState('')
  const [config,setConfig]=useState<ApiConfig>(()=>typeof window==='undefined'?emptyConfig:loadJson('im-ant-api-config',emptyConfig)),[draftConfig,setDraftConfig]=useState<ApiConfig>(()=>typeof window==='undefined'?emptyConfig:loadJson('im-ant-api-config',emptyConfig))
  const [tossConnection,setTossConnection]=useState<Connection>('idle'),[googleConnection,setGoogleConnection]=useState<Connection>('idle'),[supabaseConnection,setSupabaseConnection]=useState<Connection>('idle')
  const [notes,setNotes]=useState<StrategyNote[]>(()=>typeof window==='undefined'?[]:loadJson('im-ant-notes',[])),[noteText,setNoteText]=useState(''),[noteTag,setNoteTag]=useState('전략'),[noteFilter,setNoteFilter]=useState('전체')
  const [notesTab,setNotesTab]=useState<'notes'|'alerts'>('notes')
  const [authEmail,setAuthEmail]=useState(''),[authPassword,setAuthPassword]=useState(''),[authUser,setAuthUser]=useState<string|null>(null),[noteMessage,setNoteMessage]=useState('')
  const notesService=useMemo(()=>createStrategyNotesService(config.supabaseUrl,config.supabaseAnonKey),[config.supabaseUrl,config.supabaseAnonKey])

  useEffect(()=>{let active=true;createStockDataProvider().getStocks().then(result=>{if(active){setAllStocks(result.stocks);setCatalog(result.catalog);setMarketOverview(result.marketOverview);setSelectedGroup(current=>result.catalog.groups.some(group=>group.id===current)?current:result.catalog.groups[0]?.id??'');setDataMode(result.mode);setMarketDate(result.marketDate);setUpdatedAt(result.updatedAt);setValidation(result.validation);setRefreshState(result.refresh)}}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[])
  useEffect(()=>{let active=true;fetch('/api/market-data?status=1').then(async response=>await response.json() as {tossConfigured?:boolean;googleSheetsConfigured?:boolean}).then(status=>{if(!active)return;setTossConnection(status.tossConfigured?'ok':'idle');setGoogleConnection(status.googleSheetsConfigured?'ok':'idle')}).catch(()=>{if(active){setTossConnection('error');setGoogleConnection('error')}});return()=>{active=false}},[])
  useEffect(()=>{if(!notesService)return;let active=true;Promise.resolve().then(()=>{if(!active)return null;setSupabaseConnection('testing');return notesService.ensureAnonymousUser()}).then(async user=>{if(!active||!user)return;setAuthUser(user.id);const remote=await notesService.list();if(!active)return;const migrated=localStorage.getItem('im-ant-notes-migrated')==='1';const localNotes=loadJson<StrategyNote[]>('im-ant-notes',[]);if(!migrated&&localNotes.length){await notesService.migrate(localNotes);localStorage.setItem('im-ant-notes-migrated','1');localStorage.removeItem('im-ant-notes');setNotes(await notesService.list())}else setNotes(remote);setSupabaseConnection('ok')}).catch(()=>{if(active){setAuthUser(null);setSupabaseConnection('error')}});return()=>{active=false}},[notesService])
  useEffect(()=>{Promise.resolve().then(()=>{const params=new URLSearchParams(window.location.search),ticker=params.get('ticker');if(params.get('page')==='stock'&&ticker){setSelectedTicker(ticker.toUpperCase());setDetailTab((params.get('tab') as DetailTab)||'overview');setPage('stock')}})},[])

  const selected=allStocks.find(s=>s.ticker===selectedTicker)??allStocks[0],quick=allStocks.find(s=>s.ticker===quickTicker)??null
  const activeGroup=catalog.groups.find(group=>group.id===selectedGroup)??catalog.groups[0]
  const stocks=useMemo(()=>{const groupTickers=new Set(activeGroup?.tickers??allStocks.map(stock=>stock.ticker));return allStocks.filter(stock=>groupTickers.has(stock.ticker)).filter(s=>`${s.ticker} ${s.company} ${s.sector??''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>{const av=getValue(a,sort.key),bv=getValue(b,sort.key);if(av==null)return 1;if(bv==null)return-1;return(typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv)))*sort.dir})},[allStocks,activeGroup,query,sort])
  const navigate=(next:Page)=>{setPage(next);setMobileNav(false);setQuickTicker(null)}
  const openDetail=(ticker:string)=>{setSelectedTicker(ticker);setDetailTab('overview');navigate('stock')}
  const saveConfig=async()=>{localStorage.setItem('im-ant-api-config',JSON.stringify(draftConfig));setConfig({...draftConfig});setSupabaseConnection(draftConfig.supabaseUrl&&draftConfig.supabaseAnonKey?'testing':'idle')}
  const refreshMarket=async()=>{if(refreshing)return;setRefreshing(true);setRefreshMessage('갱신 중...');setTossConnection('testing');try{const result=await createStockDataProvider(true).getStocks();setAllStocks(result.stocks);setCatalog(result.catalog);setMarketOverview(result.marketOverview);setSelectedGroup(current=>result.catalog.groups.some(group=>group.id===current)?current:result.catalog.groups[0]?.id??'');setDataMode(result.mode);setMarketDate(result.marketDate);setUpdatedAt(result.updatedAt);setValidation(result.validation);setRefreshState(result.refresh);const status=result.refresh?.status??'failed';setRefreshMessage(status==='success'?'갱신 완료':status==='partial'?'일부 데이터 갱신 실패':'갱신 실패');setTossConnection(result.refresh?.sources.toss.status==='ok'?'ok':result.refresh?.sources.toss.status==='skipped'?'idle':'error')}catch{setRefreshMessage('갱신 실패');setTossConnection('error')}finally{setRefreshing(false)}}
  const addNote=async()=>{if(!noteText.trim())return;if(!notesService||!authUser){setNoteMessage('전략노트 저장소 연결을 확인하세요.');return}try{const created=await notesService.create({ticker:selected.ticker,content:noteText.trim(),tag:noteTag});setNotes(prev=>[created,...prev]);setNoteText('');setNoteMessage('저장됨')}catch{setNoteMessage('저장 실패 · RLS와 테이블을 확인하세요')}}
  const removeNote=async(id:string)=>{if(!notesService)return;try{await notesService.remove(id);setNotes(prev=>prev.filter(n=>n.id!==id))}catch{setNoteMessage('삭제 실패')}}
  const updateNote=async(id:string,content:string,tag:string)=>{if(!notesService)return;try{const updated=await notesService.update(id,{content,tag});setNotes(prev=>prev.map(n=>n.id===id?updated:n))}catch{setNoteMessage('수정 실패')}}
  const authenticate=async(mode:'signin'|'signup')=>{const service=createStrategyNotesService(draftConfig.supabaseUrl,draftConfig.supabaseAnonKey);if(!service){setNoteMessage('Supabase URL과 anon key를 먼저 입력하세요.');return}setSupabaseConnection('testing');try{const user=mode==='signin'?await service.signIn(authEmail,authPassword):await service.signUp(authEmail,authPassword);setAuthUser(user?.email??null);setSupabaseConnection(user?'ok':'idle');setConfig({...draftConfig});localStorage.setItem('im-ant-api-config',JSON.stringify(draftConfig));setNoteMessage(user?'Supabase 연결됨':'이메일 확인 후 로그인하세요.')}catch{setSupabaseConnection('error');setNoteMessage('인증 실패')}}
  const signOut=async()=>{await notesService?.signOut();setAuthUser(null);setSupabaseConnection('idle');setNotes([])}
  const visibleNotes=notes.filter(n=>noteFilter==='전체'||n.ticker===noteFilter||n.tag===noteFilter)
  const activeTickers=new Set(activeGroup?.tickers??allStocks.map(stock=>stock.ticker)),groupValidation=validation.filter(row=>activeTickers.has(row.ticker))
  const validationCounts={ok:groupValidation.filter(v=>v.status==='ok').length,partial:groupValidation.filter(v=>v.status==='partial').length,failed:groupValidation.filter(v=>v.status==='failed').length}

  if(!hydrated)return <div className="app-loading">MyStockLog</div>

  return <div className="app-shell"><aside className={mobileNav?'sidebar open':'sidebar'}><div className="brand"><div className="brand-mark"><b>M</b><i/><i/><i/></div><div><strong>MyStockLog</strong><span>MARKET JOURNAL</span></div><button aria-label="메뉴 닫기" className="mobile-close" onClick={()=>setMobileNav(false)}><X/></button></div><nav>{([['home','홈',Home],['stock','개별종목',FileSpreadsheet],['notes','전략노트',NotebookPen],['settings','설정',Settings]] as const).map(([key,label,Icon])=><button key={key} className={page===key?'active':''} onClick={()=>navigate(key)}><Icon/>{label}</button>)}</nav><div className="sidebar-foot"><span>MyStockLog · {APP_VERSION}</span><small>정보 비교용 · 투자 권유 아님</small></div></aside>
    <main><header><button aria-label="메뉴 열기" className="menu-button" onClick={()=>setMobileNav(true)}><Menu/></button><h1>{page==='home'?'관심종목 비교':page==='stock'?'개별종목':page==='notes'?'전략노트':'설정'}</h1><span className="app-version">{APP_VERSION}</span><div className={`connection-pill ${dataMode}`}>{loading?'데이터 확인 중':updatedAt?<><span>마지막 갱신 {formatUpdatedAt(updatedAt)} KST</span><small>종가 기준 {marketDate??'—'}</small></>:'저장된 갱신 이력 없음'}</div></header>
      {page==='home'&&<><MarketOverviewStrip items={marketOverview}/><GroupFilter groups={catalog.groups} selected={activeGroup?.id??''} onSelect={setSelectedGroup}/>{allStocks.some(stock=>stock.stale)&&<div className="stale-warning">TOSS 데이터 갱신 필요</div>}{(refreshMessage||updatedAt)&&<div className={`refresh-feedback ${refreshing?'running':refreshState?.status??''}`}><span>{refreshing?'갱신 중...':refreshMessage||`마지막 갱신 ${formatUpdatedAt(updatedAt)} KST`}</span>{updatedAt&&<small>마지막 갱신 {formatUpdatedAt(updatedAt)} KST</small>}</div>}<HomePage stocks={stocks} allCount={activeGroup?.tickers.length??allStocks.length} query={query} setQuery={setQuery} sort={sort} sortBy={key=>setSort(p=>({key,dir:p.key===key?p.dir===1?-1:1:1}))} onQuick={setQuickTicker} validation={validationCounts} refresh={refreshMarket} loading={refreshing}/></>}
      {page==='stock'&&selected&&<StockPage stock={selected} stocks={allStocks} detailTab={detailTab} setDetailTab={setDetailTab} selectTicker={setSelectedTicker} noteText={noteText} setNoteText={setNoteText} noteTag={noteTag} setNoteTag={setNoteTag} addNote={addNote} noteMessage={noteMessage}/>} 
      {page==='notes'&&<NotesPage notes={visibleNotes} allNotes={notes} filter={noteFilter} setFilter={setNoteFilter} remove={removeNote} update={updateNote} connected={supabaseConnection==='ok'} tab={notesTab} setTab={setNotesTab} stocks={allStocks} service={notesService}/>}
      {page==='settings'&&<HybridSettingsPage
        config={draftConfig} setConfig={setDraftConfig} save={saveConfig} toss={tossConnection} google={googleConnection}
        supabase={supabaseConnection} stocks={allStocks} groups={catalog.groups} email={authEmail} setEmail={setAuthEmail} password={authPassword}
        setPassword={setAuthPassword} authUser={authUser} authenticate={authenticate} signOut={signOut} message={noteMessage}/>}
    </main>{quick&&<><button aria-label="Quick View 닫기" className="scrim" onClick={()=>setQuickTicker(null)}/><QuickView stock={quick} peers={allStocks.filter(stock=>(activeGroup?.tickers??[]).includes(stock.ticker))} close={()=>setQuickTicker(null)} detail={()=>openDetail(quick.ticker)}/></>}</div>
}

function MarketOverviewStrip({items}:{items:MarketOverviewItem[]}){
  const [now,setNow]=useState(()=>new Date())
  useEffect(()=>{const timer=window.setInterval(()=>setNow(new Date()),60_000);return()=>window.clearInterval(timer)},[])
  const market=getMarketHours(now)
  return <section className="market-overview" aria-label="미국 시장현황">{items.map(item=><div key={item.key}><strong>{item.label}</strong><span>{item.value===null?'—':item.key==='us10y'?`${item.value.toFixed(2)}%`:item.key==='usdkrw'?`₩${item.value.toLocaleString('ko-KR',{maximumFractionDigits:2})}`:item.value.toLocaleString('en-US',{maximumFractionDigits:item.key==='vix'?2:0})}</span><em className={tone(item.change)}>{item.change===null?'—':item.changeUnit==='bp'?`${item.change>0?'+':''}${item.change.toFixed(0)}bp`:`${item.change>0?'+':''}${(item.change*100).toFixed(2)}%`}</em></div>)}<div className="market-session"><strong><b>US</b> 정규장</strong><span><i>ET</i> {market.et}</span><span><i>KST</i> {market.kst}</span><em className={market.status}><i/>{market.statusLabel}</em></div></section>
}

function GroupFilter({groups,selected,onSelect}:{groups:MarketCatalog['groups'];selected:string;onSelect:(id:string)=>void}){return <nav className="group-filter" aria-label="관심종목 그룹">{groups.map(group=><button key={group.id} className={selected===group.id?'active':''} aria-pressed={selected===group.id} onClick={()=>onSelect(group.id)}>{group.name}<small>{group.tickers.length}</small></button>)}</nav>}

function HomePage({stocks,allCount,query,setQuery,sort,sortBy,onQuick,validation,refresh,loading}:{stocks:StockSnapshot[];allCount:number;query:string;setQuery:(v:string)=>void;sort:{key:SortKey;dir:1|-1};sortBy:(k:SortKey)=>void;onQuick:(t:string)=>void;validation:{ok:number;partial:number;failed:number};refresh:()=>void;loading:boolean}){const proximity=(stock:StockSnapshot)=>calculateMddProximity(stock.drawdown52,mddYears.map(year=>stock.mdd[year]));const proximityTitle=(stock:StockSnapshot)=>{const result=proximity(stock);return result?`MDD 근접도 ${(result.ratio*100).toFixed(0)}%`:undefined};return <><section className="toolbar"><label><Search/><input aria-label="종목 검색" placeholder="티커, 종목명, 업종 검색" value={query} onChange={e=>setQuery(e.target.value)}/></label><button className="manual-refresh" onClick={refresh} disabled={loading} title="저장 데이터를 수동으로 갱신합니다"><RefreshCw/>수동 갱신</button><div className="validation-summary">{validation.ok+validation.partial+validation.failed>0&&`${allCount} checked · ${validation.ok} OK · ${validation.partial} partial · ${validation.failed} failed`}</div><div className="count"><strong>{stocks.length}</strong><span>/ {allCount} 종목</span></div></section><section className="desktop-table"><table><thead><tr>{columns.map(c=><th key={c.key} className={`${c.sticky?`sticky ${c.sticky}`:''} column-${String(c.key)}`}><button onClick={()=>sortBy(c.key)}>{c.label}<ChevronDown className={sort.key===c.key?(sort.dir===-1?'sorted desc':'sorted'):''}/></button></th>)}</tr></thead><tbody>{stocks.map(s=>{const mdd=proximity(s),mddClass=mdd&&mdd.level!=='normal'?`mdd-${mdd.level}`:'';return <tr key={s.ticker} onClick={()=>onQuick(s.ticker)}>{columns.map(c=>{const v=getValue(s,c.key),isMddTarget=c.key==='ticker'||c.key==='drawdown52';return <td key={c.key} title={c.key==='sector'?(s.sector??undefined):isMddTarget?proximityTitle(s):undefined} className={`${c.sticky?`sticky ${c.sticky}`:''} column-${String(c.key)} ${c.kind==='percent'&&typeof v==='number'?tone(v):''} ${isMddTarget?mddClass:''}`}>{c.key==='ticker'?<><span className="ticker-logo">{s.ticker[0]}</span><strong>{s.ticker}</strong><i className={`source-dot ${s.dataSource}`}/></>:fmt(v,c.kind)}</td>})}</tr>})}</tbody></table></section><section className="mobile-table" aria-label="모바일 관심종목 비교표"><table><thead><tr><th className="mobile-sticky">티커</th><th>현재가</th><th>전일대비</th><th>52주 고점 대비</th><th>YTD</th></tr></thead><tbody>{stocks.map(s=>{const mdd=proximity(s),mddClass=mdd&&mdd.level!=='normal'?`mdd-${mdd.level}`:'';return <tr key={s.ticker} onClick={()=>onQuick(s.ticker)}><td className={`mobile-sticky ${mddClass}`} title={proximityTitle(s)}><strong>{s.ticker}</strong><small>{s.company}</small></td><td>{fmt(s.price,'money')}</td><td className={tone(s.changePercent)}>{fmt(s.changePercent,'percent')}</td><td className={`${tone(s.drawdown52)} ${mddClass}`} title={proximityTitle(s)}>{fmt(s.drawdown52,'percent')}</td><td className={tone(s.ytdReturn)}>{fmt(s.ytdReturn,'percent')}</td></tr>})}</tbody></table></section><section className="home-glossary" aria-label="주요 지표 설명"><span><b>VIX</b> 예상 변동성 지수</span><span><b>US10Y</b> 미국 10년물 국채금리</span><span><b>PER</b> 주가 ÷ 주당순이익</span><span><b>EPS</b> 주당순이익</span><span><b>MDD</b> 고점 대비 최대 낙폭</span><span><b>ATL</b> 역대 최저가</span><span><b>ATH</b> 역대 최고가</span><span><b>YTD</b> 연초 대비 수익률</span></section><HomeInterpretationGuide/></>}

function HomeInterpretationGuide(){return <section className="interpretation-guide" aria-label="지표 해석 가이드"><article><h2>투자 판단 가이드</h2><GuideStep number="01" title="가격 위치 확인"><p>52주 고점 대비 하락률로 최근 고점에서 현재 가격이 얼마나 조정받았는지 확인합니다.</p></GuideStep><GuideStep number="02" title="MDD 근접도"><p>최근 5개년 MDD의 중앙값을 대표 MDD로 사용하고, 현재 낙폭이 과거 조정구간에 얼마나 접근했는지 비교합니다.</p><div className="mdd-guide"><span>일반<small>70% 미만</small></span><span className="watch">관심<small>70~85%</small></span><span className="near">근접<small>85~100%</small></span><span className="zone">MDD 영역<small>100% 이상</small></span></div><small className="guide-caution">색상은 매수 신호가 아니라 과거 MDD 구간 근접도를 나타내는 참고 표시입니다.</small></GuideStep><GuideStep number="03" title="그룹 내 상대 낙폭"><p>YTD와 52주 고점 대비 하락률을 현재 그룹의 다른 종목과 비교해 상대적으로 과도한 조정인지 확인합니다.</p></GuideStep><GuideStep number="04" title="EPS / PER 확인"><p>가격 하락과 함께 EPS 방향, PER 변화, 실적 전망과 기업 경쟁력 변화를 확인합니다. 많이 떨어졌다는 이유만으로 판단하지 않습니다.</p></GuideStep><GuideStep number="05" title="가격 안정성"><p>최근 저점 갱신 여부와 현재가 대비 MA20·MA60을 이용해 하락 지속 → 관찰 → 안정 시도 → 안정 상태를 구분합니다.</p></GuideStep><GuideStep number="06" title="기업 상태 최종 확인"><p>가격 위치가 좋아 보여도 실적 둔화나 기업 경쟁력 훼손 여부를 마지막으로 확인합니다.</p></GuideStep><div className="decision-flow"><b>판단 흐름</b><span>시장 환경 → 현재 낙폭 → MDD 근접도 → 그룹 내 상대 낙폭 → EPS / PER → 가격 안정성 → 기업 상태 확인</span></div><strong className="guide-core">핵심은 많이 떨어진 종목이 아니라, 기업 상태는 유지되면서 상대적으로 과도하게 조정된 종목을 확인하는 것입니다.</strong></article><article><h2>주요 지표 해석</h2><GuideMetric title="EPS" subtitle="주당순이익"><p>기업이 주식 1주당 얼마의 이익을 내는지 보여줍니다. 절대값보다 증가·감소 방향을 확인합니다.</p><div className="direction-lines"><span>EPS ↑ <small>기업 이익 증가·실적 개선 흐름</small></span><span>EPS ↓ <small>이익 감소·실적 둔화 여부 확인</small></span></div><p>GoogleFinance EPS를 실제 snapshot으로 축적하며, 완료 분기 3개부터 추세를 자동 평가합니다. 그전에는 <b>분기 데이터 축적 중</b>으로 표시합니다.</p><strong>EPS는 절대값보다 성장 방향이 중요합니다.</strong></GuideMetric><GuideMetric title="PER" subtitle="주가 ÷ EPS"><p>현재 주가가 기업 이익의 몇 배에서 거래되는지 나타냅니다. 상승은 가격 부담 확대, 하락은 부담 완화 가능성을 함께 살펴봅니다.</p><p>공통 적정값을 적용하지 않고 업종·성장률·수익성·금리·시장 기대를 고려해 해당 기업 자신의 과거 PER과 비교합니다.</p><p>완료 분기 3개부터 최근 3분기 평균 PER, 현재 PER, 평균 대비 차이를 자동 계산하며 그전에는 <b>분기 데이터 축적 중</b>으로 표시합니다.</p></GuideMetric><GuideMetric title="EPS + PER 같이 보는 법"><p>주가 ↓ · EPS ↑ 또는 유지 · PER ↓라면 이익은 유지되면서 밸류에이션 부담이 낮아지는 흐름일 수 있습니다. 주가와 EPS가 함께 크게 하락하면 실적 악화 반영 여부를 확인합니다.</p><strong>EPS는 이익의 방향을 보고, PER은 그 이익 대비 현재 주가의 부담을 판단합니다.</strong></GuideMetric><GuideMetric title="MDD" subtitle="일정 기간 중 고점 대비 최대 낙폭"><p>최근 5개년 MDD를 각각 계산하고 중앙값을 대표 MDD로 사용합니다.</p></GuideMetric><GuideMetric title="가격 안정성"><p>최근 저점과 MA20·MA60으로 단기 하락세의 안정 여부를 하락 지속·관찰·안정 시도·안정으로 구분합니다.</p></GuideMetric><GuideMetric title="기타 주요 지표"><p>ATH 역대 최고가 · ATL 역대 최저가 · YTD 연초 대비 수익률 · VIX 예상 변동성 · US10Y 미국 10년물 국채금리</p><p>TOSS 일봉은 최대 약 1,500개이므로 전체 상장 이력으로 간주하지 않습니다. 1,500개 일봉의 최고·최저를 ATH/ATL로 대체하지 않으며 전체 이력이 확보된 경우에만 표시합니다.</p></GuideMetric></article></section>}
function GuideStep({number,title,children}:{number:string;title:string;children:ReactNode}){return <section className="guide-step"><h3><i>{number}</i>{title}</h3>{children}</section>}
function GuideMetric({title,subtitle,children}:{title:string;subtitle?:string;children:ReactNode}){return <section className="guide-metric"><h3>{title}{subtitle&&<small>{subtitle}</small>}</h3>{children}</section>}

function StockPage({stock,stocks,detailTab,setDetailTab,selectTicker,noteText,setNoteText,noteTag,setNoteTag,addNote,noteMessage}:{stock:StockSnapshot;stocks:StockSnapshot[];detailTab:DetailTab;setDetailTab:(v:DetailTab)=>void;selectTicker:(v:string)=>void;noteText:string;setNoteText:(v:string)=>void;noteTag:string;setNoteTag:(v:string)=>void;addNote:()=>void;noteMessage:string}){const analysis=useMemo(()=>buildStockAnalysis(stock,stocks),[stock,stocks]);return <div className="page-wrap"><section className="stock-head"><div><select aria-label="종목 선택" value={stock.ticker} onChange={e=>selectTicker(e.target.value)}>{stocks.map(s=><option key={s.ticker}>{s.ticker}</option>)}</select><h2>{stock.company}</h2><p>{stock.sector??'업종 미분류'} · {stock.dataSource==='toss'?`TOSS${stock.storageSource?' · 저장값':''}`:'데이터 없음'}{stock.stale?' · 가격 데이터 지연':''}</p></div></section><nav className="subtabs">{detailTabs.map(tab=><button key={tab.key} className={detailTab===tab.key?'active':''} onClick={()=>setDetailTab(tab.key)}>{tab.label}</button>)}</nav>{detailTab==='overview'&&<><OverviewSnapshot stock={stock}/><OverviewAnalysis analysis={analysis}/></>}<div className="detail-layout"><section className="detail-content">{detailTab==='overview'&&<MetricGrid stock={stock}/>} {detailTab==='trend'&&<PriceTrend stock={stock} analysis={analysis}/>} {detailTab==='fundamentals'&&<><div className="info-panel"><h3>기업·실적</h3><div className="fundamental-list"><span>시가총액<strong>{fmt(stock.marketCap,'cap')}</strong></span><span>PER <i className="info-tip" title="PER은 주가를 주당순이익으로 나눈 값입니다.">ⓘ</i><strong>{fmt(stock.pe,'number')}</strong></span><span>EPS <i className="info-tip" title="EPS는 주식 1주당 순이익입니다.">ⓘ</i><strong>{fmt(stock.eps,'money')}</strong></span><span>매출 / 순이익<strong>—</strong></span></div></div><FundamentalsHistory stock={stock}/></>} {detailTab==='issues'&&<Empty title="핵심 이슈 데이터 준비 중"/>} {detailTab==='ai'&&<AnalysisDetail analysis={analysis}/>}</section><aside className="detail-aside">{detailTab==='trend'&&<TrendNarrative analysis={analysis}/>} {detailTab==='fundamentals'&&<FundamentalsNarrative stock={stock}/>}<div className="note-composer"><h3>전략노트</h3><p>{stock.ticker}</p><textarea aria-label="전략노트 내용" value={noteText} onChange={e=>setNoteText(e.target.value)} placeholder="다음 실적에서 확인할 내용을 기록하세요"/><div><select aria-label="전략노트 태그" value={noteTag} onChange={e=>setNoteTag(e.target.value)}>{tags.map(t=><option key={t}>{t}</option>)}</select><button onClick={addNote}><Save/>저장</button></div>{noteMessage&&<small>{noteMessage}</small>}</div></aside></div><AnalysisDisclaimer/></div>}

function formatZone(zone:PriceZone|null){return zone?`$${zone.low.toFixed(2)}~${zone.high.toFixed(2)}`:'분석 준비 중'}
function ZoneCard({title,zone}:{title:string;zone:PriceZone|null}){return <article><span>{title} <i className="info-tip" title={`${title}은 여러 가격 조건이 겹치는 참고 영역이며 실제 매매를 지시하지 않습니다.`}>ⓘ</i></span><strong>{formatZone(zone)}</strong><em>{zone?.status??'분석 준비 중'}</em><small>{zone?.relation??'사용 가능한 가격 기준이 없습니다.'}</small></article>}
function OverviewAnalysis({analysis}:{analysis:StockAnalysis}){return <section className="analysis-overview"><article className="analysis-summary"><h3>종합 분석</h3><h2>{analysis.title}</h2><div><span>가격 기회<strong>{analysis.opportunity.score??'—'}점 · {analysis.opportunityLabel}</strong><small>조건 충족도 {analysis.opportunity.completeness}%</small></span><span>추세 확인<strong>{analysis.trend}</strong><small>{analysis.volumeRatio===null?'거래량 데이터 부족':`거래량 평균 대비 ${(analysis.volumeRatio*100).toFixed(0)}%`}</small></span></div><p>{analysis.summary}</p></article><article className="opportunity-card expanded"><div><span>기회점수 <i className="info-tip" title="가격 위치·상대 낙폭·EPS·PER·가격 안정성을 종합한 참고 지표입니다.">ⓘ</i></span><strong>{analysis.opportunity.score??'—'} <small>/ 100</small></strong><em>{analysis.opportunityLabel}</em></div><p>{analysis.opportunityMeaning}</p><div className="opportunity-completeness"><span>데이터 충족도</span><strong>{analysis.opportunity.completeness}%</strong><i><b style={{width:`${analysis.opportunity.completeness}%`}}/></i></div><details><summary>기회점수 보는 법</summary><ul>{analysis.opportunity.items.map(item=><li key={item.key}><span>{item.label}</span><strong>{item.status}</strong><small>{item.score===null?'제외':`${Math.round(item.score)}/${item.max}`}</small></li>)}</ul><p>기회점수는 미래 수익률을 의미하지 않습니다.</p></details></article><section className="price-zones"><h3>핵심 가격대</h3><div><ZoneCard title="매수 관심 구간" zone={analysis.buyZone}/><ZoneCard title="차익관리 구간" zone={analysis.sellZone}/></div><p>보유 평균단가와 보유 비중이 반영되지 않은 종목 기준 참고 구간입니다.</p></section>{analysis.missing.length>0&&<details className="missing-data"><summary>데이터 충족도 {analysis.completeness}% · 부족 항목 보기</summary>{analysis.missing.map(item=><p key={item}>{item}</p>)}</details>}</section>}

function AnalysisDetail({analysis}:{analysis:StockAnalysis}){return <section className="analysis-detail"><h2>{analysis.title}</h2><p>{analysis.summary}</p><div><span>가격 매력도<strong>{analysis.opportunity.score??'—'}점 · {analysis.opportunityLabel}</strong><small>{analysis.opportunityMeaning}</small></span><span>추세 상태<strong>{analysis.trend}</strong><small>{analysis.arrangement}</small></span><span>거래량 확인<strong>{analysis.volumeState}</strong><small>{analysis.volumeRatio===null?'데이터 부족':`20일 평균 대비 ${(analysis.volumeRatio*100).toFixed(0)}%`}</small></span><span>매수 관심 구간<strong>{formatZone(analysis.buyZone)}</strong><small>{analysis.buyZone?.relation??'분석 준비 중'}</small></span><span>차익관리 구간<strong>{formatZone(analysis.sellZone)}</strong><small>{analysis.sellZone?.relation??'분석 준비 중'}</small></span><span>확인해야 할 변화<strong>{analysis.priceVolumeState}</strong><small>기준일 {analysis.asOf??'—'}</small></span></div><section><h3>주의사항</h3><p>하나의 신호만으로 방향을 확정하지 않습니다. 이동평균선 배열, 거래량 변화, 가격 구간 유지 여부와 데이터 충족도를 함께 확인하세요.</p></section></section>}
function TrendNarrative({analysis}:{analysis:StockAnalysis}){const maLines=(Object.keys(analysis.ma) as MaKey[]).map(key=>{const item=analysis.ma[key],period=key.slice(2);if(item.value===null)return `${period}일 평균: 데이터 부족`;const position=item.difference===null?'현재가와 비교 불가':item.difference>=0?`현재 가격이 평균보다 ${(item.difference*100).toFixed(1)}% 높음`:`현재 가격이 평균보다 ${Math.abs(item.difference*100).toFixed(1)}% 낮음`;return `${period}일 평균 ${fmt(item.value,'money')} · ${position} · 평균선 ${item.direction}`});return <section className="side-analysis"><h3>현재 흐름을 쉽게 보면</h3><strong>{analysis.trend}</strong><p className="plain-trend">{analysis.plainTrendMeaning}</p><ul>{maLines.map(line=><li key={line}>{line}</li>)}</ul><div><span>평균선 관계<b>{analysis.arrangement}</b><small>{analysis.arrangementMeaning}</small></span><span>거래 참여<b>{analysis.volumeState}</b><small>{analysis.volumeMeaning}</small></span></div><section className="next-check"><h4>지금 확인할 것</h4><p>{analysis.nextTrendCheck}</p></section><small>현재 정규장 마감값을 기준으로 한 관찰 안내이며 매수·매도 지시가 아닙니다.</small></section>}
function FundamentalsNarrative({stock}:{stock:StockSnapshot}){const result=analyzeQuarterlyFundamentals(stock.fundamentalsHistory??[],stock.pe),count=result.completed.length,title=result.ready?`EPS ${result.epsDirection} · PER 위치 확인`:'기업지표 분석 축적 중',body=result.ready?`최근 완료 분기 3개의 EPS는 ${result.epsDirection} 흐름입니다. 현재 PER은 최근 3분기 평균보다 ${result.perDifference===null?'비교할 수 없습니다':`${Math.abs(result.perDifference*100).toFixed(1)}% ${result.perDifference<=0?'낮습니다':'높습니다'}`}.`:`완료 분기 ${count}/3개가 저장되었습니다. 3개 분기가 쌓이면 EPS 방향과 현재 PER의 최근 평균 대비 위치를 자동으로 설명합니다.`;return <section className="side-analysis fundamentals-narrative"><h3>기업·실적 해석</h3><strong>{title}</strong><p>{body}</p><div><span>현재 EPS<b>{fmt(stock.eps,'number')}</b></span><span>현재 PER<b>{fmt(stock.pe,'number')}</b></span></div><small>매일 저장되는 값은 분기별로 묶어 분석하며, 데이터가 부족하면 임의 평가하지 않습니다.</small></section>}
function AnalysisDisclaimer(){return <p className="analysis-disclaimer">본 분석은 가격·이동평균선·거래량·실적지표를 바탕으로 계산한 참고정보입니다. 표시된 가격대는 미래 수익이나 실제 매매 결과를 보장하지 않으며, 보유 평균단가와 개인의 투자기간·위험성향은 반영되지 않을 수 있습니다.</p>}

type HistoryPeriod='ALL'|'1Y'|'3Y'
function FundamentalsHistory({stock}:{stock:StockSnapshot}){return <><section className="fund-history"><FundamentalSeries title="EPS 추이" metric="eps" points={stock.fundamentalsHistory??[]}/><FundamentalSeries title="PER 추이" metric="per" points={stock.fundamentalsHistory??[]}/><p className="fund-combo-note">EPS 상승 + PER 하락은 이익은 증가하면서 밸류에이션 부담이 낮아지는 흐름일 수 있습니다.</p></section><QuarterlyFundamentals stock={stock}/></>}
function FundamentalSeries({title,metric,points}:{title:string;metric:'eps'|'per';points:NonNullable<StockSnapshot['fundamentalsHistory']>}){const valid=points.filter(point=>typeof point[metric]==='number').map(point=>({date:point.snapshotDate,value:point[metric] as number})),[period,setPeriod]=useState<HistoryPeriod>('ALL'),latest=valid.at(-1)?.date,cutoff=(years:number)=>{if(!latest)return'';const date=new Date(`${latest}T00:00:00Z`);date.setUTCFullYear(date.getUTCFullYear()-years);return date.toISOString().slice(0,10)},available1y=Boolean(valid[0]&&valid[0].date<=cutoff(1)),available3y=Boolean(valid[0]&&valid[0].date<=cutoff(3)),filtered=period==='ALL'?valid:valid.filter(point=>point.date>=cutoff(period==='1Y'?1:3)),values=filtered.map(point=>point.value),average=values.length?values.reduce((sum,value)=>sum+value,0)/values.length:null,current=values.at(-1)??null,comparison=metric==='per'&&current!==null&&average?current/average-1:null;return <article className="fund-series"><div className="fund-series-head"><h3>{title}</h3><div>{(['ALL','1Y','3Y'] as HistoryPeriod[]).map(option=><button key={option} disabled={option==='1Y'?!available1y:option==='3Y'?!available3y:false} className={period===option?'active':''} onClick={()=>setPeriod(option)}>{option==='ALL'?'전체':option}</button>)}</div></div><div className="fund-summary">{metric==='eps'?<><span>현재 EPS<strong>{fmt(current,'number')}</strong></span><span>누적 시작일<strong>{valid[0]?.date??'2026-08-20'}</strong></span><span>데이터 포인트<strong>{valid.length}개</strong></span></>:<><span>현재 PER<strong>{fmt(current,'number')}</strong></span><span>누적 기간 평균<strong>{fmt(average,'number')}</strong></span><span>최저 / 최고<strong>{values.length?`${Math.min(...values).toFixed(2)} / ${Math.max(...values).toFixed(2)}`:'—'}</strong></span></>}</div>{comparison!==null&&<p className="per-comparison">누적 평균 대비 {fmt(comparison,'percent')}</p>}{filtered.length>=2?<div className="fund-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={filtered} margin={{top:10,right:8,left:-8,bottom:2}}><CartesianGrid stroke="#202b38" vertical={false}/><XAxis dataKey="date" minTickGap={32} tick={{fill:'#778493',fontSize:8}} tickFormatter={value=>String(value).slice(5)}/><YAxis width={46} domain={['auto','auto']} tick={{fill:'#778493',fontSize:8}}/><Tooltip contentStyle={{background:'#0d141d',border:'1px solid #293543',borderRadius:7,fontSize:10}} formatter={value=>[Number(value).toFixed(2),metric.toUpperCase()]}/><Line dataKey="value" stroke={metric==='eps'?'#61d6a1':'#f4c45e'} dot={false} strokeWidth={2}/></LineChart></ResponsiveContainer></div>:<div className="fund-empty"><strong>누적 데이터 준비 중</strong><span>2026-08-20부터 기록</span><span>현재 {valid.length}개 데이터 포인트</span></div>}<table className="fund-table"><thead><tr><th>날짜</th><th>{metric.toUpperCase()}</th></tr></thead><tbody>{filtered.slice(-6).reverse().map(point=><tr key={point.date}><td>{point.date}</td><td>{point.value.toFixed(2)}</td></tr>)}</tbody></table><p className="fund-note">{metric==='eps'?'EPS는 절대값보다 증가·감소 방향을 확인하는 것이 중요합니다.':'PER은 절대적인 적정값보다 해당 기업의 과거 수준과 비교해 보는 것이 유용합니다.'}</p></article>}
function QuarterlyFundamentals({stock}:{stock:StockSnapshot}){const analysis=analyzeQuarterlyFundamentals(stock.fundamentalsHistory??[],stock.pe),chart=analysis.quarters.map(item=>({quarter:item.quarter.replace('-',' '),eps:item.eps,per:item.perAverage})),progress=`분기 데이터 ${Math.min(analysis.completed.length,3)}/3 · ${analysis.ready?'평가 활성':'축적 중'}`;return <section className="quarter-history"><article><h3>EPS 분기 추이</h3><div className="quarter-summary"><span>현재 EPS<strong>{fmt(stock.eps,'number')}</strong></span><span>전분기 대비<strong>{fmt(analysis.quarters.at(-1)?.epsChange??null,'percent')}</strong></span><span>상태<strong>{analysis.epsDirection??'데이터 축적 중'}</strong></span></div>{analysis.quarters.length>=2?<QuarterChart data={chart} metric="eps"/>:<div className="quarter-empty">{progress}<small>3개 완료 분기부터 평가</small></div>}<div className="quarter-list">{analysis.quarters.slice(-4).map(item=><span key={item.quarter}>{item.quarter.replace('-',' ')}{!item.completed&&<i>진행 중</i>}<strong>{fmt(item.eps,'number')}</strong></span>)}</div></article><article><h3>PER 분기 추이</h3><div className="quarter-summary"><span>현재 PER<strong>{fmt(stock.pe,'number')}</strong></span><span>최근 3분기 평균<strong>{fmt(analysis.perAverage3,'number')}</strong></span><span>평균 대비<strong>{fmt(analysis.perDifference,'percent')}</strong></span></div>{analysis.quarters.length>=2?<QuarterChart data={chart} metric="per"/>:<div className="quarter-empty">{progress}<small>3개 완료 분기부터 평가</small></div>}<div className="quarter-list per">{analysis.quarters.slice(-4).map(item=><span key={item.quarter}>{item.quarter.replace('-',' ')}{!item.completed&&<i>진행 중</i>}<strong>평균 {fmt(item.perAverage,'number')} · 최저 {fmt(item.perMin,'number')} · 최고 {fmt(item.perMax,'number')} · 말 {fmt(item.perEnd,'number')}</strong></span>)}</div></article></section>}
function QuarterChart({data,metric}:{data:{quarter:string;eps:number|null;per:number|null}[];metric:'eps'|'per'}){return <div className="quarter-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={data} margin={{top:10,right:8,left:-8,bottom:2}}><CartesianGrid stroke="#202b38" vertical={false}/><XAxis dataKey="quarter" tick={{fill:'#778493',fontSize:8}}/><YAxis width={46} domain={['auto','auto']} tick={{fill:'#778493',fontSize:8}}/><Tooltip contentStyle={{background:'#0d141d',border:'1px solid #293543',borderRadius:7,fontSize:10}}/><Line dataKey={metric} connectNulls={false} stroke={metric==='eps'?'#61d6a1':'#f4c45e'} strokeWidth={2}/></LineChart></ResponsiveContainer></div>}

function PriceTrend({stock,analysis}:{stock:StockSnapshot;analysis:StockAnalysis}){const [period,setPeriod]=useState<Period>('1Y');const [visible,setVisible]=useState<Record<MaKey,boolean>>({ma20:true,ma60:true,ma120:false,ma200:true});const data=useMemo(()=>{const history=new Map(stock.priceHistory.map(point=>[point.date,point]));const enriched=analysis.series.map((point,index)=>{const raw=history.get(point.date),prior=analysis.series[index-1],priorVolumes=stock.priceHistory.filter(item=>item.date<point.date&&typeof item.volume==='number').slice(-20).map(item=>item.volume as number);return {...point,volume:raw?.volume??null,volumeAverage:priorVolumes.length===20?priorVolumes.reduce((sum,value)=>sum+value,0)/20:null,direction:prior?point.price>prior.price?'up':point.price<prior.price?'down':'flat':'flat'}});if(!enriched.length)return[];const latest=new Date(`${enriched.at(-1)!.date}T00:00:00Z`),start=new Date(latest),amount=Number(period.slice(0,-1)),unit=period.at(-1);if(unit==='M')start.setUTCMonth(start.getUTCMonth()-amount);else start.setUTCFullYear(start.getUTCFullYear()-amount);return enriched.filter(point=>point.date>=start.toISOString().slice(0,10))},[analysis.series,period,stock.priceHistory]);const colors:Record<MaKey,string>={ma20:'#61d6a1',ma60:'#77a7ff',ma120:'#c58cff',ma200:'#ff8a65'},volumeFmt=(value:number)=>value>=1e9?`${(value/1e9).toFixed(1)}B`:value>=1e6?`${(value/1e6).toFixed(0)}M`:`${(value/1e3).toFixed(0)}K`;return <><div className="chart-card"><div className="chart-toolbar"><div className="period-buttons">{periods.map(p=><button key={p} className={period===p?'active':''} onClick={()=>setPeriod(p)}>{p}</button>)}</div><div className="ma-toggles">{(Object.keys(visible) as MaKey[]).map(key=><button key={key} className={visible[key]?'active':''} onClick={()=>setVisible(value=>({...value,[key]:!value[key]}))}>{key.toUpperCase()}</button>)}</div></div><div className="ma-current-grid">{(Object.keys(analysis.ma) as MaKey[]).map(key=><span key={key} title={`${key.toUpperCase()}은 최근 ${key.slice(2)}거래일 종가 평균입니다.`}><i style={{background:colors[key]}}/>{key.toUpperCase()} <strong>{fmt(analysis.ma[key].value,'money')}</strong><small>{fmt(analysis.ma[key].difference,'percent')} · {analysis.ma[key].direction}</small></span>)}</div>{data.length>1?<><div className="chart-canvas"><ResponsiveContainer width="100%" height="100%"><LineChart data={data} margin={{top:12,right:8,left:0,bottom:4}}><CartesianGrid stroke="#202b38" vertical={false}/><XAxis dataKey="date" minTickGap={45} tick={{fill:'#778493',fontSize:9}} tickFormatter={v=>String(v).slice(5)}/><YAxis domain={['auto','auto']} width={52} tick={{fill:'#778493',fontSize:9}} tickFormatter={v=>`$${Number(v).toFixed(0)}`}/><Tooltip contentStyle={{background:'#0d141d',border:'1px solid #293543',borderRadius:8,fontSize:11}} formatter={(v,name)=>[`$${Number(v).toFixed(2)}`,String(name).toUpperCase()]}/><Line dataKey="price" name="Price" stroke="#f4c45e" dot={false} strokeWidth={2}/>{(Object.keys(visible) as MaKey[]).map(key=>visible[key]?<Line key={key} dataKey={key} name={key} stroke={colors[key]} dot={false} strokeWidth={1.4} connectNulls/>:null)}</LineChart></ResponsiveContainer></div><div className="volume-chart"><h3>일별 거래량 <i className="info-tip" title="색상은 거래일의 가격 방향이며 매수량·매도량을 의미하지 않습니다.">ⓘ</i></h3><ResponsiveContainer width="100%" height="100%"><ComposedChart data={data} margin={{top:8,right:8,left:0,bottom:3}}><CartesianGrid stroke="#202b38" vertical={false}/><XAxis dataKey="date" minTickGap={45} tick={{fill:'#778493',fontSize:8}} tickFormatter={v=>String(v).slice(5)}/><YAxis width={52} tick={{fill:'#778493',fontSize:8}} tickFormatter={volumeFmt}/><Tooltip contentStyle={{background:'#0d141d',border:'1px solid #293543',borderRadius:8,fontSize:10}} formatter={(v,name)=>[volumeFmt(Number(v)),name==='volume'?'거래량':'20일 평균']}/><Bar dataKey="volume" name="volume">{data.map(point=><Cell key={point.date} fill={point.direction==='up'?'#48b987':point.direction==='down'?'#e45d62':'#657282'}/>)}</Bar><Line dataKey="volumeAverage" name="volumeAverage" stroke="#f4c45e" dot={false} strokeWidth={1.4} connectNulls/></ComposedChart></ResponsiveContainer></div></>:<Empty title="해당 기간 가격 데이터가 없습니다"/>}</div><section className="trend-confirm"><div><span>추세 상태<strong>{analysis.trend}</strong><small>{analysis.arrangement}</small></span><span>거래량 강도 <i className="info-tip" title="최근 거래일 거래량을 직전 20거래일 평균과 비교합니다.">ⓘ</i><strong>{analysis.volumeRatio===null?'데이터 부족':`20일 평균 대비 ${(analysis.volumeRatio*100).toFixed(0)}%`}</strong><small>{analysis.volumeState}</small></span></div><p>{analysis.trendSummary}</p></section><Returns stock={stock}/><LearningGuides/></>}

function LearningGuides(){return <section className="learning-guides"><details><summary>이동평균선 보는 법</summary><p>MA20은 약 1개월, MA60은 약 3개월, MA120은 약 6개월, MA200은 약 10개월의 평균 종가와 추세를 보여줍니다. 정배열은 단기부터 장기까지 상승 흐름이 정돈된 상태이며 역배열은 여러 기간에서 하락 흐름이 이어지는 상태입니다.</p><small>이동평균선은 실제 투자자의 평균 매수가가 아니라 일정 기간의 평균 종가입니다.</small></details><details><summary>거래량 보는 법</summary><p>녹색 막대는 주가 상승일, 빨간색 막대는 주가 하락일의 전체 거래 규모입니다. 선은 최근 20거래일 평균 거래량입니다.</p><small>녹색은 매수량, 빨간색은 매도량을 의미하지 않습니다.</small></details><details><summary>MA와 거래량 함께 보는 법</summary><p>MA 상향 돌파에 거래량 증가가 동반되면 추세 회복의 신뢰도가 높아질 수 있습니다. 하향 이탈과 거래량 증가가 함께 나타나면 약세 지속 여부를 확인합니다. 거래량이 줄어든 움직임은 추가 방향 확인이 필요합니다.</p></details></section>}

function Returns({stock}:{stock:StockSnapshot}){return <div className="returns-row">{[['1M',stock.return1m],['3M',stock.return3m],['6M',stock.return6m],['YTD',stock.ytdReturn],['1Y',stock.return1y],['3Y',stock.return3y],['5Y',stock.return5y]].map(([label,value])=><span key={String(label)}>{label}<strong className={tone(value as MetricValue)}>{fmt(value as MetricValue,'percent')}</strong></span>)}</div>}
const stockExtremes=(stock:StockSnapshot)=>{
  const history52=stock.priceHistory.length?stock.priceHistory.filter(point=>{const end=new Date(`${stock.priceHistory.at(-1)!.date}T00:00:00Z`);end.setUTCFullYear(end.getUTCFullYear()-1);return point.date>=end.toISOString().slice(0,10)}):[]
  const extremeDate=(direction:'high'|'low')=>{if(!history52.length)return null;const point=history52.reduce((best,current)=>{const bestValue=direction==='high'?(best.high??best.adjustedClose??best.close):(best.low??best.adjustedClose??best.close);const currentValue=direction==='high'?(current.high??current.adjustedClose??current.close):(current.low??current.adjustedClose??current.close);return direction==='high'?(currentValue>bestValue?current:best):(currentValue<bestValue?current:best)});return point.date.replaceAll('-','.')}
  return {highDate:extremeDate('high'),lowDate:extremeDate('low')}
}
function OverviewSnapshot({stock}:{stock:StockSnapshot}){
  const latest=stock.priceHistory.at(-1)?.date
  const start=latest?new Date(`${latest}T00:00:00Z`):null
  start?.setUTCMonth(start.getUTCMonth()-1)
  const recent=stock.priceHistory.filter(point=>!start||point.date>=start.toISOString().slice(0,10)).map(point=>({date:point.date,price:point.adjustedClose??point.close}))
  const prices=recent.map(point=>point.price)
  const monthHigh=prices.length?Math.max(...prices):null,monthLow=prices.length?Math.min(...prices):null,monthLast=prices.at(-1)??null
  const priceChange=stock.price!==null&&stock.changePercent!==null&&stock.changePercent!==-1?stock.price-stock.price/(1+stock.changePercent):null
  const {highDate,lowDate}=stockExtremes(stock)
  return <section className="overview-snapshot overview-snapshot-top">
    <div className="snapshot-price"><span>현재가</span><strong>{fmt(stock.price,'money')} <small>USD</small></strong><em className={tone(stock.changePercent)}>{fmt(priceChange,'money')} ({fmt(stock.changePercent,'percent')})</em><small>최근 저장 시장 데이터 기준</small></div>
    <div className="snapshot-chart snapshot-chart-detailed"><div className="snapshot-chart-head"><span>최근 1개월 가격 흐름 <small>일봉</small></span><div><b>고가 {fmt(monthHigh,'money')}</b><b>저가 {fmt(monthLow,'money')}</b><b>최근 {fmt(monthLast,'money')}</b></div></div>{recent.length>1?<OverviewPriceChart data={recent}/>:<div className="snapshot-chart-body"><b className="chart-unavailable">최근 1개월 가격 데이터가 없습니다.</b></div>}</div>
    <div className="snapshot-stat"><span>시가총액</span><strong>{fmt(stock.marketCap,'cap')}</strong></div><div className="snapshot-stat"><span>PER (TTM)</span><strong>{fmt(stock.pe,'number')}</strong></div><div className="snapshot-stat"><span>EPS (TTM)</span><strong>{fmt(stock.eps,'money')}</strong></div><div className="snapshot-stat"><span>52주 고점</span><strong>{fmt(stock.high52,'money')}</strong><small>{highDate??'—'}</small></div><div className="snapshot-stat"><span>52주 저점</span><strong>{fmt(stock.low52,'money')}</strong><small>{lowDate??'—'}</small></div>
  </section>
}
function OverviewPriceChart({data}:{data:{date:string;price:number}[]}){
  const containerRef=useRef<HTMLDivElement>(null)
  const [width,setWidth]=useState(0)
  useEffect(()=>{const element=containerRef.current;if(!element)return;const update=()=>setWidth(Math.max(0,Math.floor(element.clientWidth)));update();const observer=new ResizeObserver(update);observer.observe(element);return()=>observer.disconnect()},[])
  return <div className="snapshot-chart-body" ref={containerRef}>{width>0&&<LineChart width={width} height={118} data={data} margin={{top:5,right:8,left:0,bottom:3}}><CartesianGrid stroke="#1b3048" vertical={false}/><XAxis dataKey="date" minTickGap={36} tick={{fill:'#6f8299',fontSize:8}} tickFormatter={value=>String(value).slice(5).replace('-','.')}/><YAxis domain={['auto','auto']} width={43} tick={{fill:'#6f8299',fontSize:8}} tickFormatter={value=>`$${Number(value).toFixed(0)}`}/><Tooltip contentStyle={{background:'#0b1522',border:'1px solid #315477',borderRadius:8,fontSize:10}} labelFormatter={value=>String(value)} formatter={value=>[`$${Number(value).toFixed(2)}`,'종가']}/><Line dataKey="price" stroke="#58a6ff" dot={false} activeDot={{r:3,fill:'#f4c45e'}} strokeWidth={1.35}/></LineChart>}</div>
}
function MetricGrid({stock}:{stock:StockSnapshot}){
  const {highDate,lowDate}=stockExtremes(stock)
  const performance=[['YTD',stock.ytdReturn],['3개월',stock.return3m],['1년',stock.return1y],['3년',stock.return3y]] as const
  return <div className="stock-overview">
    <section className="overview-panels">
      <article className="overview-panel earnings"><h3><i/>실적</h3><div className="overview-grid earnings-grid"><span className="overview-pair">ATH (역대 최고가)<strong>{fmt(stock.ath,'money')}</strong></span><span className="overview-pair">ATL (역대 최저가)<strong>{fmt(stock.atl,'money')}</strong></span>{mddYears.map(year=><span className="overview-third" key={year}>MDD {year}<strong className={tone(stock.mdd[year])}>{fmt(stock.mdd[year],'percent')}</strong></span>)}</div></article>
      <article className="overview-panel levels"><h3><i/>가격 레벨</h3><div className="overview-grid level-grid"><span>52주 고점<strong>{fmt(stock.high52,'money')}</strong><small>{highDate??'—'}</small></span><span>52주 저점<strong>{fmt(stock.low52,'money')}</strong><small>{lowDate??'—'}</small></span><span className="wide">52주 고점 대비<strong className={tone(stock.drawdown52)}>{fmt(stock.drawdown52,'percent')}</strong></span></div></article>
      <article className="overview-panel performance"><h3><i/>성과 요약</h3><div className="overview-grid performance-grid">{performance.map(([label,value])=><span key={label}>{label}<strong className={tone(value)}>{fmt(value,'percent')} {value===null?'':value>0?'▲':'▼'}</strong></span>)}</div></article>
    </section>
    <p className="overview-footnote">모든 수치는 USD 기준이며, 가격 및 성과 지표는 저장된 종가 기준입니다.</p>
  </div>
}

function NotesPage({notes,allNotes,filter,setFilter,remove,update,connected,tab,setTab,stocks,service}:{notes:StrategyNote[];allNotes:StrategyNote[];filter:string;setFilter:(v:string)=>void;remove:(id:string)=>void;update:(id:string,content:string,tag:string)=>void;connected:boolean;tab:'notes'|'alerts';setTab:(value:'notes'|'alerts')=>void;stocks:StockSnapshot[];service:StrategyNotesService|null}){const [editing,setEditing]=useState<string|null>(null),[draft,setDraft]=useState(''),[draftTag,setDraftTag]=useState('전략');const filters=['전체',...Array.from(new Set(allNotes.flatMap(n=>[n.ticker,n.tag])))];return <div className="page-wrap"><nav className="notes-tabs"><button className={tab==='notes'?'active':''} onClick={()=>setTab('notes')}>전략노트</button><button className={tab==='alerts'?'active':''} onClick={()=>setTab('alerts')}><Bell/>알림</button></nav>{tab==='alerts'?<PriceAlertsPage stocks={stocks} service={service} connected={connected}/>:<><div className="section-head"><div><h2>모든 판단 메모</h2><p>{connected?'Supabase 동기화':'저장소 연결 필요'}</p></div><select aria-label="전략노트 필터" value={filter} onChange={e=>setFilter(e.target.value)}>{filters.map(f=><option key={f}>{f}</option>)}</select></div>{notes.length?<section className="notes-board">{notes.map(note=><article key={note.id}><div><strong>{note.ticker}</strong><time>{new Date(note.createdAt).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'})}</time><button aria-label="메모 수정" onClick={()=>{setEditing(note.id);setDraft(note.content);setDraftTag(note.tag)}}><Pencil/></button><button aria-label="메모 삭제" onClick={()=>remove(note.id)}><Trash2/></button></div>{editing===note.id?<><textarea value={draft} onChange={e=>setDraft(e.target.value)}/><select value={draftTag} onChange={e=>setDraftTag(e.target.value)}>{tags.map(t=><option key={t}>{t}</option>)}</select><button className="note-save" onClick={()=>{update(note.id,draft,draftTag);setEditing(null)}}>저장</button></>:<><p>{note.content}</p><span>#{note.tag}</span></>}</article>)}</section>:<Empty title={connected?'아직 기록된 전략노트가 없습니다':'전략노트 저장소 연결을 확인하세요'}/>}</>}</div>}

function PriceAlertsPage({stocks,service,connected}:{stocks:StockSnapshot[];service:StrategyNotesService|null;connected:boolean}){
  const [dashboard,setDashboard]=useState<AlertDashboard|null>(null),[message,setMessage]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('전체'),[busy,setBusy]=useState(false)
  const [pushDiagnostic,setPushDiagnostic]=useState<string[]>([])
  const reload=async(init=false)=>{try{if(init)await alertAction(service,{action:'init',stocks:stocks.map(stock=>({ticker:stock.ticker,company:stock.company}))});setDashboard(await loadAlerts(service))}catch(error){setMessage(error instanceof Error?error.message:'알림 정보를 불러오지 못했습니다.')}}
  // Loading is intentionally tied to the authenticated storage connection and catalog size.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(()=>{void Promise.resolve().then(()=>reload(true))},[service,connected,stocks.length])
  const act=async(body:Record<string,unknown>)=>{setBusy(true);try{setDashboard(await alertAction(service,body));setMessage('설정이 저장되었습니다.')}catch(error){setMessage(error instanceof Error?error.message:'설정 저장 실패')}finally{setBusy(false)}}
  const addDiagnostic=(value:string)=>setPushDiagnostic(previous=>[...previous,value])
  const stageMessage=(stage:PushSubscribeStage)=>({
    'service-worker-registering':'Service Worker: 등록 중',
    'service-worker-ready':'Service Worker: ready',
    'vapid-ready':'VAPID 공개키: 확인됨',
    'subscription-existing':'Push subscription: 기존 구독 확인',
    'subscription-created':'Push subscription: success',
    'd1-saved':'D1 저장: success',
  })[stage]
  const allow=async()=>{
    setPushDiagnostic(['버튼 클릭: 실행','푸시 진단: 지원 여부 확인'])
    setMessage('권한 요청을 준비하고 있습니다.')
    if(!support.supported){setMessage('이 환경은 Web Push를 지원하지 않습니다. iPhone에서는 홈 화면에 설치한 앱으로 실행하세요.');addDiagnostic('푸시 진단: 지원 안 됨');return}
    addDiagnostic('푸시 진단: 지원됨')
    if(Notification.permission==='denied'){setMessage('iPhone 설정 → 알림 → MyStockLog에서 알림을 허용해 주세요.');addDiagnostic('권한 결과: denied');return}
    setBusy(true)
    setMessage('권한 요청 중...')
    addDiagnostic(`권한 요청 전: ${Notification.permission}`)
    try{
      // iOS requires this call to start directly inside the user's tap handler.
      const permissionPromise=Notification.permission==='granted'?Promise.resolve<NotificationPermission>('granted'):Notification.requestPermission()
      addDiagnostic('권한 요청: 실행')
      const result=await permissionPromise
      addDiagnostic(`권한 결과: ${result}`)
      if(result==='denied'){setMessage('알림 권한이 거부되었습니다. iPhone 설정 → 알림 → MyStockLog에서 허용해 주세요.');return}
      if(result==='default'){setMessage('알림 권한 선택이 완료되지 않았습니다. 알림 허용을 다시 눌러 선택해 주세요.');return}
      setMessage('푸시 구독을 연결하고 있습니다...')
      const subscribed=await subscribePush(service,stage=>addDiagnostic(stageMessage(stage)))
      addDiagnostic(`사용자 인증: connected (${subscribed.authSource==='sites'?'MyStockLog Sites':'Supabase'})`)
      addDiagnostic(`Endpoint: ${subscribed.endpoint?'생성됨':'없음'}`)
      setDashboard(previous=>previous?{...previous,pushSubscribed:true}:previous)
      setMessage('휴대폰 알림이 연결되었습니다.')
      await reload()
    }catch(error){const detail=error instanceof Error?error.message:'알림 연결 실패';addDiagnostic(`오류: ${detail}`);setMessage(detail)}finally{setBusy(false)}
  }
  const test=async()=>{try{await testPush(service);setMessage('테스트 알림을 보냈습니다.')}catch(error){setMessage(error instanceof Error?error.message:'테스트 알림 실패')}}
  const support=detectPushSupport(),permission=support.permission==='unsupported'?'지원 안 됨':support.permission==='granted'?'허용됨':support.permission==='denied'?'차단됨':'허용 필요',settings=dashboard?.settings??[],stockMap=new Map(stocks.map(stock=>[stock.ticker,stock])),rows=settings.map(setting=>{const stock=stockMap.get(setting.ticker),analysis=stock?buildStockAnalysis(stock,stocks):null;return{setting,stock,analysis}}).filter(row=>`${row.setting.ticker} ${row.setting.company??''}`.toLowerCase().includes(query.toLowerCase())).filter(row=>filter==='전체'||filter==='보유 종목'&&row.setting.is_holding||filter==='매수 관심 알림'&&row.setting.buy_enabled||filter==='차익관리 알림'&&row.setting.sell_enabled||filter==='구간 진입'&&(row.setting.buy_state==='inside'||row.setting.sell_state==='inside')||filter==='구간 접근'&&(row.setting.buy_state==='approaching'||row.setting.sell_state==='approaching')||filter==='데이터 부족'&&(!row.analysis?.buyZone||!row.analysis?.sellZone))
  const zone=(value:PriceZone|null|undefined)=>value?`$${value.low.toFixed(2)}~${value.high.toFixed(2)}`:'데이터 부족'
  const allPaused=settings.length>0&&settings.every(item=>item.paused)
  return <section className="alerts-page"><div className="section-head"><div><h2>가격구간 알림</h2><p>매일 정규장 마감 데이터 갱신 후 매수 관심 구간과 차익관리 구간 진입 여부를 확인합니다.</p></div></div><div className="alert-status"><span>알림 권한<strong>{permission}</strong></span><span>푸시 구독<strong>{dashboard?.pushSubscribed?'연결됨':'연결 필요'}</strong></span><span>마지막 확인<strong>{dashboard?.lastRun?.completed_at?formatUpdatedAt(dashboard.lastRun.completed_at):'—'}</strong></span><span>정규장 마감일<strong>{dashboard?.lastRun?.market_date??'—'}</strong></span><span>다음 확인<strong>06:40 KST 갱신 직후</strong></span><span>감시 종목<strong>{settings.filter(item=>!item.paused&&(item.buy_enabled||item.sell_enabled)).length}</strong></span><span>최근 알림<strong>{dashboard?.events.length??0}</strong></span></div><div className="alert-actions"><button onClick={allow} disabled={busy}><Bell/>{busy?'권한 요청 중...':'알림 허용'}</button><button onClick={test} disabled={!dashboard?.pushSubscribed}>테스트 알림</button><button onClick={()=>act({action:'bulk_buy',value:true})}>전체 매수 알림 켜기</button><button onClick={()=>act({action:'bulk_buy',value:false})}>전체 매수 알림 끄기</button><button onClick={()=>act({action:'bulk_holding_sell',value:true})}>보유 종목 관리 알림 켜기</button><button onClick={()=>act({action:'pause_all',value:!allPaused})}>{allPaused?'전체 알림 다시 시작':'전체 일시정지'}</button></div>{message&&<p className="alert-message">{message}</p>}{pushDiagnostic.length>0&&<details className="push-diagnostic" open><summary>푸시 연결 진단</summary>{pushDiagnostic.map((item,index)=><span key={`${item}-${index}`}>{item}</span>)}</details>}<div className="alert-filters"><label><Search/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="티커·종목명 검색"/></label><select value={filter} onChange={event=>setFilter(event.target.value)}>{['전체','보유 종목','매수 관심 알림','차익관리 알림','구간 접근','구간 진입','데이터 부족'].map(item=><option key={item}>{item}</option>)}</select></div><div className="alert-table"><div className="alert-row head"><b>종목</b><b>현재가 / 기준일</b><b>가격구간</b><b>현재 상태</b><b>설정</b></div>{rows.map(({setting,stock,analysis})=><div className="alert-row" key={setting.ticker}><div><strong>{setting.ticker}</strong><small>{setting.company}</small></div><div><strong>{fmt(stock?.price??null,'money')}</strong><small>{stock?.priceHistory.at(-1)?.date??'—'}</small></div><div><span>매수 {zone(analysis?.buyZone)}</span><span>관리 {zone(analysis?.sellZone)}</span></div><div><span>매수 {setting.buy_state}</span><span>관리 {setting.sell_state}</span><small>마지막 알림 {setting.last_alert_at?formatUpdatedAt(setting.last_alert_at):'—'}</small></div><div className="alert-checks"><label><input type="checkbox" checked={Boolean(setting.is_holding)} onChange={event=>act({action:'update',ticker:setting.ticker,field:'is_holding',value:event.target.checked})}/>보유 중</label><label><input type="checkbox" checked={Boolean(setting.buy_enabled)} onChange={event=>act({action:'update',ticker:setting.ticker,field:'buy_enabled',value:event.target.checked})}/>매수 관심 알림</label><label><input type="checkbox" checked={Boolean(setting.sell_enabled)} onChange={event=>act({action:'update',ticker:setting.ticker,field:'sell_enabled',value:event.target.checked})}/>차익관리 알림</label></div></div>)}</div><section className="recent-alerts"><h3>최근 알림</h3>{dashboard?.events.length?dashboard.events.slice(0,10).map(event=><article key={event.id}><strong>{event.title}</strong><p>{event.body}</p><small>{event.market_date} · {event.push_status}</small></article>):<p>발생한 알림이 없습니다.</p>}</section></section>
}

function HybridSettingsPage({config,setConfig,save,toss,google,supabase,stocks,groups,message}:{config:ApiConfig;setConfig:(v:ApiConfig)=>void;save:()=>void;toss:Connection;google:Connection;supabase:Connection;stocks:StockSnapshot[];groups:MarketCatalog['groups'];email:string;setEmail:(v:string)=>void;password:string;setPassword:(v:string)=>void;authUser:string|null;authenticate:(m:'signin'|'signup')=>void;signOut:()=>void;message:string}){
  const field=(key:ApiTextKey,label:string,placeholder:string,secret=false)=><label><span>{label}</span><input type={secret?'password':'text'} value={config[key]} placeholder={placeholder} autoComplete="off" onChange={e=>setConfig({...config,[key]:e.target.value})}/></label>
  const status=(value:Connection)=>value==='testing'?'확인 중':value==='ok'?'연결됨':value==='error'?'연결 실패':'미설정'
  return <div className="page-wrap settings-page"><section className="settings-intro"><KeyRound/><div><h2>데이터 연결</h2></div></section>
    <section className="settings-card"><div className="settings-title"><div><h3>토스증권</h3><p>현재가 · 일봉 OHLCV</p></div><span className={`status ${toss}`}>{status(toss)}</span></div><small className="settings-message">서버 보안 환경변수로 관리됩니다.</small></section>
    <section className="settings-card"><div className="settings-title"><div><h3>GoogleFinance · Google Sheets</h3><p>EPS · PER · 시가총액 · 시장지표</p></div><span className={`status ${google}`}>{status(google)}</span></div></section>
    <section className="settings-card"><div className="settings-title"><div><h3>전략노트 저장소</h3><p>익명 세션으로 자동 연결됩니다.</p></div><span className={`status ${supabase}`}>{status(supabase)}</span></div><div className="form-grid">{field('supabaseUrl','Project URL','https://….supabase.co')}{field('supabaseAnonKey','Anon Key','Supabase anon key',true)}</div><small className="settings-message">브라우저의 사이트 데이터를 삭제하면 익명 사용자 세션도 초기화될 수 있습니다.</small>{message&&<small className="settings-message">{message}</small>}</section>
    <section className="settings-card"><div className="settings-title"><div><h3>OpenAI</h3></div><span className="status planned">연결 준비</span></div>{field('openAiKey','OpenAI API Key','sk-…',true)}</section>
    <section className="watchlist-card"><div><h3>현재 등록 종목</h3><p>{stocks.length}개 종목</p></div><div>{stocks.map(stock=><span key={stock.ticker}>{stock.ticker}</span>)}</div></section><section className="group-status-card"><h3>그룹별 등록 종목</h3>{groups.map(group=><div key={group.id}><strong>{group.name}</strong><span>{group.tickers.join(' · ')}</span></div>)}</section><button className="save-settings" onClick={save}><RefreshCw/>설정 저장</button></div>
}

function Empty({title}:{title:string}){return <div className="empty-state"><div>MSL</div><h3>{title}</h3></div>}
function QuickView({stock,peers,close,detail}:{stock:StockSnapshot;peers:StockSnapshot[];close:()=>void;detail:()=>void}){
  const [quickPeriod,setQuickPeriod]=useState<QuickPeriod>('3M')
  const priceChange=stock.price!==null&&stock.changePercent!==null&&stock.changePercent!==-1?stock.price-stock.price/(1+stock.changePercent):null
  const marketStatus=(()=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const part=(type:string)=>parts.find(item=>item.type===type)?.value??'';const minutes=Number(part('hour'))*60+Number(part('minute'));return !['Sat','Sun'].includes(part('weekday'))&&minutes>=570&&minutes<960?'마켓 오픈':'정규장 마감'})()
  const periodReturns={'3M':stock.return3m,'1Y':stock.return1y,'3Y':stock.return3y}
  const periodTitles={'3M':'최근 3개월 가격 추이','1Y':'최근 1년 가격 추이','3Y':'최근 3년 가격 추이'}
  const selectedReturn=periodReturns[quickPeriod]
  const chartHistory=quickChartData(stock.priceHistory,quickPeriod,selectedReturn)
  const opportunity=opportunityScore(stock,peers)
  return <aside className="quick-view" role="dialog" aria-modal="true" aria-label={`${stock.ticker} Quick View`}><div className="quick-header"><div><p className="eyebrow">QUICK VIEW</p><h2>Quick View</h2></div><button aria-label="닫기" className="quick-close" onClick={close}><X/></button></div><div className="quick-title"><span className="ticker-logo large">{stock.ticker[0]}</span><div><h3>{stock.company.toUpperCase()}</h3><p>{stock.ticker} · {stock.sector??'업종 미분류'}</p></div></div>
    <section className="opportunity-card"><div><span>기회점수</span><strong>{opportunity.score??'—'} <small>/ 100</small></strong><em>{opportunity.status}</em></div><div className="opportunity-completeness"><span>데이터 충족도</span><strong>{opportunity.completeness}%</strong><i><b style={{width:`${opportunity.completeness}%`}}/></i></div><p>설정한 투자 조건 충족 정도</p><ul>{opportunity.items.map(item=><li key={item.key}><span>{item.label}</span><strong>{item.status}</strong><small>{item.score===null?'축적 중':`${Math.round(item.score)}/${item.max}`}</small></li>)}</ul></section>
    <section className="quick-section"><h4>현재 상태</h4><div className="quick-current"><div className="quick-price"><span>현재가</span><strong>{fmt(stock.price,'money')}</strong><em className={tone(stock.changePercent)}>{fmt(priceChange,'money')} · {fmt(stock.changePercent,'percent')}</em></div><span className="market-status">{marketStatus}</span></div><div className="quick-grid three"><span>시가총액<strong>{fmt(stock.marketCap,'cap')}</strong></span><span>PER (TTM)<strong>{fmt(stock.pe,'number')}</strong></span><span>EPS (TTM)<strong>{fmt(stock.eps,'money')}</strong></span></div></section>
    <section className="quick-section"><h4>가격 위치</h4><div className="quick-grid"><span>52주 고점<strong>{fmt(stock.high52,'money')}</strong></span><span>52주 저점<strong>{fmt(stock.low52,'money')}</strong></span><span>52주 고점 대비<strong className={tone(stock.drawdown52)}>{fmt(stock.drawdown52,'percent')}</strong></span><span>YTD<strong className={tone(stock.ytdReturn)}>{fmt(stock.ytdReturn,'percent')}</strong></span></div><div className="quick-mdd-label">최근 5개년 MDD</div><div className="quick-grid three quick-mdd">{mddYears.map(year=><span key={year}>MDD {year}<strong className={tone(stock.mdd[year])}>{fmt(stock.mdd[year],'percent')}</strong></span>)}</div></section>
    <section className="quick-section"><h4>성과 요약</h4><div className="quick-performance">{(['3M','1Y','3Y'] as const).map(period=><button key={period} className={quickPeriod===period?'active':''} aria-pressed={quickPeriod===period} onClick={()=>setQuickPeriod(period)}><span>{period}</span><strong className={tone(periodReturns[period])}>{fmt(periodReturns[period],'percent')}</strong></button>)}</div></section>
    <section className="quick-section"><h4>{periodTitles[quickPeriod]}</h4>{chartHistory.sufficient&&chartHistory.data.length>1?<div className="quick-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartHistory.data} margin={{top:8,right:4,left:-12,bottom:0}}><XAxis dataKey="date" tick={false} axisLine={{stroke:'#263342'}} tickLine={false}/><YAxis domain={['auto','auto']} width={55} tick={{fill:'#778493',fontSize:9}} tickFormatter={value=>`$${Number(value).toFixed(0)}`} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#0d141d',border:'1px solid #293543',borderRadius:7,fontSize:10}} labelFormatter={value=>String(value)} formatter={value=>[`$${Number(value).toFixed(2)}`,'Price']}/><Line dataKey="price" stroke="#f4c45e" dot={false} strokeWidth={2}/></LineChart></ResponsiveContainer></div>:<div className="quick-empty">{quickPeriod==='3M'?'3개월':quickPeriod==='1Y'?'1년':'3년'} 데이터가 충분하지 않습니다.</div>}</section>
    <div className="quick-actions"><button className="detail-button" onClick={detail}>상세분석 보기 <ChevronRight/></button><button className="quick-bottom-close" onClick={close}>닫기</button></div></aside>
}

export default App
